// Build the request body for POST /basket from the EAN list in the Settings node.
//
// Everything above the entry marker near the bottom is a pure function with no
// n8n globals, so it is unit-tested with node --test on integrations/n8n/test/*.test.mjs.
// After editing this file run `node integrations/n8n/build.mjs`; that copies it
// into the Build basket request Code node of weekly-ean-price-monitor.json.

const MAX_ITEMS = 200;
const EAN_LENGTHS = [8, 12, 13, 14];

function toBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'string') return !['false', '0', 'no', 'off'].includes(value.trim().toLowerCase());
  return Boolean(value);
}

// A GTIN-12 and the same code padded to GTIN-13 are one product, so compare
// EANs without their leading zeros.
function eanKey(ean) {
  return ean.replace(/^0+(?=[0-9])/, '');
}

function problem(headline, reason, action, rejected, duplicates) {
  return {
    status: 'problem',
    headline,
    reason,
    action,
    text: `${headline}\n\n${reason}\n\n${action}`,
    count: 0,
    rejected,
    duplicates,
  };
}

// Returns { status: 'ok', body, count, rejected, duplicates } or, when the list
// cannot be sent, { status: 'problem', headline, reason, action, text, ... }.
// It never throws: a bad list goes to the problem branch instead of crashing.
function buildBasketRequest(eansInput, options) {
  const includeLoyalty = toBool(options && options.includeLoyalty, true);
  const pieces = Array.isArray(eansInput) ? eansInput : String(eansInput ?? '').split(/[\r\n,;]+/);
  const items = [];
  const seen = new Set();
  const rejected = [];
  const duplicates = [];
  for (const piece of pieces) {
    const input = String(piece ?? '').trim();
    if (input === '') continue;
    if (!/^[0-9]+$/.test(input)) {
      rejected.push({ input, reason: 'not all digits' });
    } else if (!EAN_LENGTHS.includes(input.length)) {
      rejected.push({ input, reason: `${input.length} digits, an EAN has 8, 12, 13 or 14` });
    } else if (seen.has(eanKey(input))) {
      duplicates.push(input);
    } else {
      seen.add(eanKey(input));
      items.push({ ean: input });
    }
  }

  if (items.length === 0) {
    const shown = rejected.slice(0, 5).map((r) => r.input).join(', ');
    return problem(
      'no valid EANs in Settings',
      rejected.length > 0
        ? `None of the ${rejected.length} entries in the eans field is a valid EAN (8, 12, 13 or 14 digits). First few: ${shown}.`
        : 'The eans field in Settings is empty.',
      'Put one EAN per line in the eans field of the Settings node, then run the workflow again. Nothing was sent to Apify.',
      rejected,
      duplicates,
    );
  }
  if (items.length > MAX_ITEMS) {
    return problem(
      'too many EANs',
      `The list has ${items.length} valid EANs but the basket endpoint takes at most ${MAX_ITEMS} per request.`,
      `Remove ${items.length - MAX_ITEMS} of them, or split the list across two copies of this workflow, each with its own sheet tab. Nothing was sent to Apify.`,
      rejected,
      duplicates,
    );
  }
  return {
    status: 'ok',
    count: items.length,
    body: { items, live: false, includeLoyalty },
    rejected,
    duplicates,
  };
}

// --- n8n entry ---
const settings = $('Settings').first().json;
return [{ json: buildBasketRequest(settings.eans, { includeLoyalty: settings.includeLoyalty }) }];

// Classify the answer of the Price the basket HTTP Request node.
//
// Returns { status: 'ok', answer, warnings, ... } for a usable answer, or
// { status: 'problem', headline, reason, action, ... } with a plain-English
// reason for the problem email. A retailer that is down is only a warning.
//
// Everything above the entry marker near the bottom is a pure function with no
// n8n globals, so it is unit-tested with node --test on integrations/n8n/test/*.test.mjs.
// After editing this file run `node integrations/n8n/build.mjs`; that copies it
// into the Check the answer Code node of weekly-ean-price-monitor.json.

const STALE_DAYS = 10;
const WEEK_PATTERN = /^\d{4}-W\d{2}$/;
const NETWORK_CODES = ['ETIMEDOUT', 'ECONNRESET', 'ECONNREFUSED', 'ECONNABORTED', 'ENOTFOUND', 'EAI_AGAIN', 'EHOSTUNREACH', 'EPIPE'];

function problem(fields) {
  const p = { status: 'problem', statusCode: null, code: null, retryAfter: null, details: null, ...fields };
  p.text = `${p.headline}\n\n${p.reason}\n\n${p.action}`;
  return p;
}

function headerValue(headers, name) {
  if (!headers || typeof headers !== 'object') return null;
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === name) return String(headers[key]);
  }
  return null;
}

function parseBody(body) {
  if (typeof body !== 'string') return body;
  try {
    return JSON.parse(body);
  } catch (e) {
    return body;
  }
}

// The endpoint answers errors as { error: { code, message, details } }.
function readError(body) {
  if (body && typeof body === 'object' && body.error && typeof body.error === 'object') {
    return { code: body.error.code ?? null, message: String(body.error.message ?? ''), details: body.error.details ?? null };
  }
  if (body && typeof body === 'object' && typeof body.error === 'string') {
    return { code: null, message: body.error, details: null };
  }
  if (typeof body === 'string' && body.trim() !== '') {
    return { code: null, message: body.trim().slice(0, 200), details: null };
  }
  return { code: null, message: '', details: null };
}

function classifyError(statusCode, body, retryAfter) {
  const err = readError(body);
  const said = err.message ? ` The endpoint said: ${err.message.endsWith('.') ? err.message : `${err.message}.`}` : '';
  const seconds = retryAfter && /^[0-9]+$/.test(retryAfter) ? `${retryAfter} seconds` : retryAfter;
  const wait = seconds ? ` The endpoint asks you to wait ${seconds} before trying again.` : '';
  const tag = err.code ? `${statusCode} ${err.code}` : `${statusCode}`;
  const found = { statusCode, code: err.code, retryAfter, details: err.details };

  if (statusCode === 400) {
    return problem({
      ...found,
      headline: 'the basket request was invalid',
      reason: `The endpoint rejected the request as invalid (${tag}).${said}`,
      action: 'Check the eans field in Settings: 8, 12, 13 or 14 digits each, at most 200. Then run the workflow again.',
    });
  }
  if (statusCode === 401 || statusCode === 403) {
    return problem({
      ...found,
      headline: 'Apify refused the token',
      reason: `Apify answered ${tag}: the token was not accepted for this Actor.${said}`,
      action: 'Check the Header Auth credential: name Authorization, value Bearer, a space, then your token. The token needs the account-level Actors Run permission and Permission mode Full access (Apify refuses a Standby call from a token that can run only this one Actor).',
    });
  }
  if (statusCode === 402) {
    return problem({
      ...found,
      headline: 'Apify spend limit reached',
      reason: `Apify says the spend limit has been reached (${tag}), so the basket was not priced.${said}`,
      action: 'Raise the usage limit on your Apify account or wait for it to reset, then run the workflow again.',
    });
  }
  if (statusCode === 429) {
    return problem({
      ...found,
      headline: 'the basket endpoint is busy',
      reason: `The endpoint is busy (${tag}).${said}${wait}`,
      action: 'Run the workflow again after the wait. This workflow prices from the weekly snapshot (live is off), so this should be rare.',
    });
  }
  if (statusCode === 503) {
    if (err.code === 'index-unavailable') {
      return problem({
        ...found,
        headline: 'the weekly price index is not available',
        reason: `The endpoint could not load the weekly price index (${tag}).${said}${wait}`,
        action: 'This usually clears within minutes. Run the workflow again after the wait. If it stays broken, check the weekly snapshot run in Apify Console.',
      });
    }
    if (err.code === 'charging-failed') {
      return problem({
        ...found,
        headline: 'the endpoint could not charge for the request',
        reason: `The endpoint could not record the charge (${tag}), so it returned no prices.${said}${wait}`,
        action: 'Run the workflow again after the wait. If it repeats, check the billing and spend limit on your Apify account.',
      });
    }
    if (err.code === 'pricing-not-configured') {
      return problem({
        ...found,
        headline: 'the Actor pricing is not set up',
        reason: `The Actor has no price for basket lines configured yet (${tag}). This is a problem on the Actor side.${said}${wait}`,
        action: 'There is nothing to change in this workflow. Try again later, or tell the Actor author if it persists.',
      });
    }
    return problem({
      ...found,
      headline: 'the basket endpoint is unavailable',
      reason: `The endpoint is temporarily unavailable (${tag}).${said}${wait}`,
      action: 'Run the workflow again after the wait.',
    });
  }
  if (statusCode === 504) {
    return problem({
      ...found,
      headline: 'pricing the basket timed out',
      reason: `The endpoint took too long to price the basket (${tag}).${said}`,
      action: 'Run the workflow again. If it repeats, shorten the eans list or split it across two copies of this workflow.',
    });
  }
  if (statusCode === 404) {
    return problem({
      ...found,
      headline: 'the basket endpoint was not found',
      reason: `Nothing answered at that address (${tag}).${said}`,
      action: 'Check standbyUrl in Settings. It should be the Actor Standby address, without /basket on the end.',
    });
  }
  return problem({
    ...found,
    headline: `unexpected answer (${statusCode})`,
    reason: `The endpoint answered ${tag}.${said}${wait}`,
    action: 'Open the failed execution in n8n and look at the output of Price the basket for the full answer.',
  });
}

function isIsoWeek(value) {
  return typeof value === 'string' && WEEK_PATTERN.test(value);
}

// The error n8n hands over can carry the request it made, headers and token
// included, so it is never printed or serialised. Only a few named fields with a
// strict shape, or a known network error code found in a plain message, are used.
function describeFailure(err) {
  const found = [];
  if (err && typeof err === 'object') {
    if (typeof err.name === 'string' && err.name !== 'Error' && /^[A-Za-z]{1,40}$/.test(err.name)) found.push(err.name);
    if (typeof err.code === 'string' && /^[A-Za-z0-9_]{1,40}$/.test(err.code)) found.push(err.code);
    const status = String(err.httpCode ?? err.statusCode ?? '');
    if (/^[0-9]{3}$/.test(status)) found.push(`HTTP ${status}`);
  } else if (typeof err === 'string') {
    for (const code of NETWORK_CODES) {
      if (err.includes(code)) found.push(code);
    }
  }
  return found.length > 0 ? found.join(', ') : 'no response from the endpoint';
}

function checkAnswer(response) {
  const res = response || {};
  if (res.statusCode === undefined || res.statusCode === null) {
    return problem({
      headline: 'no answer from the basket endpoint',
      reason: `The request did not get an HTTP answer: ${describeFailure(res.error)}.`,
      action: 'Check standbyUrl in Settings and that n8n can reach the internet, then run the workflow again. If the request timed out after 300 seconds it may still have been charged, so look at your Apify usage first.',
    });
  }
  const statusCode = Number(res.statusCode);
  const body = parseBody(res.body);
  if (!(statusCode >= 200 && statusCode < 300)) {
    return classifyError(statusCode, body, headerValue(res.headers, 'retry-after'));
  }
  if (!body || typeof body !== 'object' || !Array.isArray(body.retailers) || body.retailers.length === 0) {
    return problem({
      statusCode,
      headline: 'unexpected answer',
      reason: `The endpoint answered ${statusCode} but the body has no list of retailers.`,
      action: 'Open the failed execution in n8n and look at the output of Price the basket. If the answer format has changed, this workflow needs updating.',
    });
  }
  const snapshot = body.snapshot || {};
  const weeks = [snapshot.week];
  for (const r of body.retailers) {
    if (r && r.snapshot && r.snapshot.week !== undefined && r.snapshot.week !== null) weeks.push(r.snapshot.week);
  }
  const wrongWeeks = weeks.filter((w) => !isIsoWeek(w));
  if (wrongWeeks.length > 0) {
    const got = wrongWeeks[0] === undefined || wrongWeeks[0] === null ? 'none' : String(wrongWeeks[0]).slice(0, 20);
    return problem({
      statusCode,
      headline: 'unexpected snapshot week',
      reason: `The snapshot week in the answer is not an ISO week such as 2026-W40 (got ${got}), so nothing was written to the sheet.`,
      action: 'Open the failed execution in n8n and look at the output of Price the basket. If the answer format has changed, this workflow needs updating.',
    });
  }
  if (snapshot.stale === true) {
    const age = typeof snapshot.ageDays === 'number' ? `, ${snapshot.ageDays} days old` : '';
    return problem({
      statusCode,
      headline: 'prices are stale',
      reason: `Prices are more than ${STALE_DAYS} days old, the weekly snapshot may have failed (snapshot ${snapshot.week ?? 'unknown'}${age}). Nothing was written to the sheet.`,
      action: 'Look at the weekly snapshot run in Apify Console; the index is rebuilt on Sundays. Run this workflow again once a fresh snapshot exists.',
    });
  }

  const warnings = [];
  let available = 0;
  let matchedLines = 0;
  for (const r of body.retailers) {
    if (r.available === false) {
      warnings.push({ retailer: r.retailer, reason: r.reason ?? 'unavailable' });
      continue;
    }
    available += 1;
    matchedLines += Array.isArray(r.lines) ? r.lines.length : 0;
    if (r.snapshot && r.snapshot.stale === true) {
      warnings.push({ retailer: r.retailer, reason: `prices are more than ${STALE_DAYS} days old` });
    }
  }
  if (available === 0) {
    return problem({
      statusCode,
      headline: 'no retailer could be priced',
      reason: `Every retailer was unavailable: ${warnings.map((w) => `${w.retailer} (${w.reason})`).join(', ')}.`,
      action: 'Check the weekly snapshot run in Apify Console, then run the workflow again.',
    });
  }
  if (matchedLines === 0) {
    return problem({
      statusCode,
      headline: 'no EAN matched anywhere',
      reason: 'None of the EANs in Settings matched a product at any retailer this week.',
      action: 'Check the EANs (copy one from a product page to test). If they matched before, the weekly snapshot may be incomplete: look at the snapshot run in Apify Console.',
    });
  }
  return { status: 'ok', statusCode, answer: body, warnings, week: snapshot.week ?? null, matchedLines };
}

// --- n8n entry ---
return [{ json: checkAnswer($input.first().json) }];

// Flatten the basket answer into one sheet row per matched line per retailer.
//
// Row columns, in the order the Google Sheet header row must have them:
// week, pricedAt, retailer, ean, name, packSize, price, loyaltyPrice,
// effectivePrice, currency, matchedBy, confidence, retailerProductId, url,
// recordedAt. A missing packSize or loyaltyPrice becomes an empty cell. A line
// with no name, price or retailer product id is an error, never a half-empty row.
// A snapshot week that is not an ISO week returns a problem item instead of rows;
// the entry block turns that into an error so it reaches the problem email.
//
// Everything above the entry marker near the bottom is a pure function with no
// n8n globals, so it is unit-tested with node --test on integrations/n8n/test/*.test.mjs.
// After editing this file run `node integrations/n8n/build.mjs`; that copies it
// into the Flatten prices Code node of weekly-ean-price-monitor.json.

const WEEK_PATTERN = /^\d{4}-W\d{2}$/;

function toBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'string') return !['false', '0', 'no', 'off'].includes(value.trim().toLowerCase());
  return Boolean(value);
}

function isNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function blank(value) {
  return value === undefined || value === null ? '' : value;
}

function fail(where, what) {
  throw new Error(`flattenPrices: ${where} has no ${what}`);
}

// A snapshot week that is not an ISO week (2026-W40) is a problem item, not rows.
function badWeek(got) {
  const shown = got === undefined || got === null ? 'none' : String(got).slice(0, 20);
  const headline = 'unexpected snapshot week';
  const reason = `The snapshot week in the answer is not an ISO week such as 2026-W40 (got ${shown}), so no rows were made.`;
  const action = 'Open the failed execution in n8n and look at the output of Price the basket. If the answer format has changed, this workflow needs updating.';
  return { status: 'problem', headline, reason, action, text: `${headline}\n\n${reason}\n\n${action}` };
}

// answer: the body of a 200 answer from POST /basket (the `answer` field the
// Check the answer node passes on). settings: { includeLoyalty }.
// nowIso: the ISO time of this run, written to the recordedAt column.
function flattenPrices(answer, settings, nowIso) {
  if (!answer || !Array.isArray(answer.retailers)) fail('the answer', 'list of retailers');
  const top = answer.snapshot || {};
  const weeks = [top.week];
  for (const r of answer.retailers) {
    if (r && r.available !== false && r.snapshot && r.snapshot.week !== undefined && r.snapshot.week !== null) weeks.push(r.snapshot.week);
  }
  const wrongWeeks = weeks.filter((w) => typeof w !== 'string' || !WEEK_PATTERN.test(w));
  if (wrongWeeks.length > 0) return badWeek(wrongWeeks[0]);
  if (typeof answer.currency !== 'string' || answer.currency === '') fail('the answer', 'currency');
  const includeLoyalty = toBool(settings && settings.includeLoyalty, true);

  const rows = [];
  const unmatched = [];
  const unavailable = [];
  const eans = [];
  const seenEans = new Set();
  const noteEan = (ean) => {
    if (!seenEans.has(ean)) {
      seenEans.add(ean);
      eans.push(ean);
    }
  };

  for (const retailer of answer.retailers) {
    const retailerName = retailer && retailer.retailer;
    if (typeof retailerName !== 'string' || retailerName === '') fail('a retailer entry', 'retailer name');
    if (retailer.available === false) {
      unavailable.push({ retailer: retailerName, reason: blank(retailer.reason) });
      continue;
    }
    const snap = retailer.snapshot || top;
    for (const line of retailer.lines || []) {
      const where = `${retailerName} line ${line && line.index}`;
      const ean = line && line.input && line.input.ean;
      const m = line && line.matched;
      if (!ean) fail(where, 'input ean');
      if (!m) fail(where, 'matched product');
      if (typeof m.name !== 'string' || m.name === '') fail(where, 'name');
      if (!isNumber(m.price)) fail(where, 'price');
      if (m.retailerProductId === undefined || m.retailerProductId === null || m.retailerProductId === '') {
        fail(where, 'retailerProductId');
      }
      const loyalty = isNumber(m.loyaltyPrice) ? m.loyaltyPrice : null;
      noteEan(String(ean));
      rows.push({
        week: snap.week || top.week,
        pricedAt: m.pricedAt || snap.pricedAt || top.pricedAt || '',
        retailer: retailerName,
        ean: String(ean),
        name: m.name,
        packSize: blank(m.packSize),
        price: m.price,
        loyaltyPrice: loyalty === null ? '' : loyalty,
        effectivePrice: includeLoyalty && loyalty !== null && loyalty < m.price ? loyalty : m.price,
        currency: answer.currency,
        matchedBy: blank(m.matchedBy),
        confidence: isNumber(m.confidence) ? m.confidence : '',
        retailerProductId: String(m.retailerProductId),
        url: blank(m.url),
        recordedAt: nowIso,
      });
    }
    const missing = [];
    for (const u of retailer.unmatched || []) {
      const ean = u && u.input && u.input.ean;
      if (ean) {
        missing.push(String(ean));
        noteEan(String(ean));
      }
    }
    if (missing.length > 0) unmatched.push({ retailer: retailerName, eans: missing });
  }

  return {
    status: 'ok',
    week: top.week,
    pricedAt: top.pricedAt || '',
    currency: answer.currency,
    recordedAt: nowIso,
    includeLoyalty,
    rowCount: rows.length,
    rows,
    unmatched,
    unavailable,
    eans,
  };
}

// --- n8n entry ---
const settings = $('Settings').first().json;
const flat = flattenPrices($input.first().json.answer, { includeLoyalty: settings.includeLoyalty }, new Date().toISOString());
if (flat.status === 'problem') throw new Error(`${flat.headline}: ${flat.reason}`);
return [{ json: flat }];

// Compare this week's prices with the history read from the Google Sheet.
//
// For each retailer and EAN it finds the latest earlier week in the history and
// works out the % change of effectivePrice. Movers change by thresholdPct or
// more, up or down. It also lists items priced last week but not this week,
// lists items that now match a different retailer product (not compared, since
// a different product is not a price move), marks a week that is already in the
// sheet (so nothing is appended twice) and, when there is no earlier week at
// all, records a baseline with no alerts.
//
// Everything above the entry marker near the bottom is a pure function with no
// n8n globals, so it is unit-tested with node --test on integrations/n8n/test/*.test.mjs.
// After editing this file run `node integrations/n8n/build.mjs`; that copies it
// into the Compare with last week Code node of weekly-ean-price-monitor.json.

const DEFAULT_THRESHOLD_PCT = 5;
const WEEK_PATTERN = /^[0-9]{4}-W[0-9]{2}$/;

// A sheet that already holds numbers can hand EANs and product ids back without
// their leading zeros, so compare them without.
function eanKey(value) {
  return String(value ?? '').trim().replace(/^0+(?=[0-9])/, '');
}

function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  const cleaned = value.trim().replace(/[£$€, ]/g, '');
  if (cleaned === '') return null;
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Plain text. In the HTML every string that came from the endpoint goes through
// esc(), so wrap this in esc() there; the text version uses it as it is.
function money(value, currency) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '';
  return currency === 'GBP' ? `£${n.toFixed(2)}` : `${n.toFixed(2)} ${currency ?? ''}`.trim();
}

function signedPct(value) {
  return `${value > 0 ? '+' : ''}${value.toFixed(1)}%`;
}

function link(name, url) {
  const label = esc(name);
  const safe = typeof url === 'string' && (url.startsWith('https://') || url.startsWith('http://'));
  return safe ? `<a href='${esc(url)}'>${label}</a>` : label;
}

// History rows come back from Google Sheets as text or numbers. Keep the ones
// with a week, retailer, EAN and price, and count the rest so the note can say so.
// productId is the retailerProductId cell, or '' when it is empty.
function readHistory(history) {
  const rows = [];
  let ignored = 0;
  for (const raw of Array.isArray(history) ? history : []) {
    if (!raw || typeof raw !== 'object' || Object.keys(raw).length === 0) continue;
    const week = String(raw.week ?? '').trim();
    const retailer = String(raw.retailer ?? '').trim();
    const ean = eanKey(raw.ean);
    const price = toNumber(raw.effectivePrice) ?? toNumber(raw.price);
    if (!WEEK_PATTERN.test(week) || retailer === '' || ean === '' || price === null) {
      ignored += 1;
      continue;
    }
    rows.push({
      week,
      retailer,
      ean,
      price,
      name: String(raw.name ?? ''),
      url: String(raw.url ?? ''),
      productId: String(raw.retailerProductId ?? '').trim(),
    });
  }
  return { rows, ignored };
}

// The latest history row of one retailer and EAN from a week before `week`.
// ISO week labels (2026-W39) sort correctly as plain text.
function latestBefore(rows, week) {
  let best = null;
  for (const r of rows || []) {
    if (r.week < week && (best === null || r.week >= best.week)) best = r;
  }
  return best;
}

function renderEmail(r, flat, rejected) {
  const cur = flat.currency;
  const unmatched = flat.unmatched || [];
  const unavailable = flat.unavailable || [];
  const html = [`<p>${esc(r.summary)}</p>`];
  const text = [r.summary];

  if (r.alerts.length > 0) {
    const body = r.alerts
      .map((a) => {
        const fuzzy = a.matchedBy && a.matchedBy !== 'ean' ? ` <em>(matched by ${esc(a.matchedBy)}, confidence ${esc(a.confidence)})</em>` : '';
        return `<tr><td>${esc(a.retailer)}</td><td>${link(a.name, a.url)}${fuzzy}</td><td>${esc(a.ean)}</td><td>${esc(money(a.oldPrice, cur))}</td><td>${esc(money(a.newPrice, cur))}</td><td>${esc(signedPct(a.changePct))}</td><td>${esc(a.fromWeek)} to ${esc(a.toWeek)}</td></tr>`;
      })
      .join('');
    html.push(`<table border='1' cellpadding='4' cellspacing='0'><tr><th>Retailer</th><th>Product</th><th>EAN</th><th>Was</th><th>Now</th><th>Change</th><th>Weeks</th></tr>${body}</table>`);
    for (const a of r.alerts) {
      text.push(`${a.retailer}: ${a.name} (EAN ${a.ean}) ${money(a.oldPrice, cur)} -> ${money(a.newPrice, cur)}, ${signedPct(a.changePct)}, ${a.fromWeek} to ${a.toWeek}`);
    }
  }
  if (r.gone.length > 0) {
    const items = r.gone
      .map((g) => `<li>${esc(g.retailer)}: ${link(g.name || g.ean, g.url)} (EAN ${esc(g.ean)}), last price ${esc(money(g.lastPrice, cur))}</li>`)
      .join('');
    html.push(`<p>No longer priced (priced in ${esc(r.previousWeek)}, missing this week):</p><ul>${items}</ul>`);
    text.push('No longer priced:');
    for (const g of r.gone) text.push(`${g.retailer}: ${g.name || g.ean} (EAN ${g.ean}), last price ${money(g.lastPrice, cur)}`);
  }
  if (r.changedProduct.length > 0) {
    const items = r.changedProduct
      .map((c) => `<li>${esc(c.retailer)}: EAN ${esc(c.ean)} was ${esc(c.oldName || 'an unnamed product')} (product ${esc(c.oldProductId)}, ${esc(money(c.oldPrice, cur))}), now ${link(c.name, c.url)} (product ${esc(c.newProductId)}, ${esc(money(c.newPrice, cur))})</li>`)
      .join('');
    html.push(`<p>Matched a different product than last time (not compared, so not counted as price moves):</p><ul>${items}</ul>`);
    text.push('Matched a different product than last time (not compared):');
    for (const c of r.changedProduct) {
      text.push(`${c.retailer}: EAN ${c.ean} was ${c.oldName || 'an unnamed product'} (product ${c.oldProductId}, ${money(c.oldPrice, cur)}), now ${c.name} (product ${c.newProductId}, ${money(c.newPrice, cur)})`);
    }
  }
  if (unmatched.length > 0) {
    const items = unmatched.map((u) => `<li>${esc(u.retailer)}: ${esc(u.eans.join(', '))}</li>`).join('');
    html.push(`<p>Not found this week (no price recorded):</p><ul>${items}</ul>`);
    for (const u of unmatched) text.push(`Not found at ${u.retailer}: ${u.eans.join(', ')}`);
  }
  if (unavailable.length > 0) {
    const names = unavailable.map((u) => `${u.retailer} (${u.reason || 'unavailable'})`).join(', ');
    html.push(`<p>Could not be priced this week: ${esc(names)}.</p>`);
    text.push(`Could not be priced this week: ${names}.`);
  }
  if (rejected.length > 0) {
    const names = rejected.map((x) => x.input).join(', ');
    html.push(`<p>Ignored in the eans field (not valid EANs): ${esc(names)}.</p>`);
    text.push(`Ignored in the eans field (not valid EANs): ${names}.`);
  }
  for (const w of r.warnings) {
    html.push(`<p>${esc(w)}</p>`);
    text.push(w);
  }
  const basis = flat.includeLoyalty === false ? 'shelf price' : 'effective price (the loyalty price when it is lower than the shelf price)';
  html.push(`<p>Prices from the UK Supermarket Price Scraper on Apify, weekly snapshot of ${esc(flat.pricedAt)}. Changes compare the ${basis}.</p>`);
  return { html: html.join(''), text: text.join('\n') };
}

// flat: the output of Flatten prices. history: the rows of the sheet, one plain
// object each. options: { thresholdPct, rejected }.
function compareWeeks(flat, history, options) {
  if (!flat || !Array.isArray(flat.rows) || typeof flat.week !== 'string' || !WEEK_PATTERN.test(flat.week)) {
    throw new Error('compareWeeks: expected the output of Flatten prices (rows and an ISO week)');
  }
  const opts = options || {};
  const rejected = Array.isArray(opts.rejected) ? opts.rejected : [];
  const warnings = [];
  let thresholdPct = toNumber(opts.thresholdPct);
  if (thresholdPct === null || thresholdPct < 0) {
    warnings.push(`thresholdPct was not a number of zero or more, so ${DEFAULT_THRESHOLD_PCT} was used.`);
    thresholdPct = DEFAULT_THRESHOLD_PCT;
  }

  const thisWeek = flat.week;
  const { rows: past, ignored } = readHistory(history);
  if (ignored > 0) warnings.push(`${ignored} history rows were ignored (no week, retailer, EAN or price).`);
  const alreadyRecorded = past.some((r) => r.week === thisWeek);
  const earlier = past.filter((r) => r.week < thisWeek);
  const previousWeek = earlier.reduce((max, r) => (max === null || r.week > max ? r.week : max), null);

  const byKey = new Map();
  for (const r of earlier) {
    const key = `${r.retailer}|${r.ean}`;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key).push(r);
  }

  // Movers: this week against the latest earlier week of the same retailer and
  // EAN, but only when both weeks matched the same retailer product. A different
  // retailerProductId (a fuzzy match that switched product, say) is not a price
  // move; it goes to changedProduct. An empty product id on either side cannot
  // be checked, so that pair is compared as before.
  const alerts = [];
  const changedProduct = [];
  const currentKeys = new Set();
  let compared = 0;
  let newItems = 0;
  for (const row of flat.rows) {
    const key = `${row.retailer}|${eanKey(row.ean)}`;
    currentKeys.add(key);
    const prev = latestBefore(byKey.get(key), row.week);
    if (prev === null) {
      newItems += 1;
      continue;
    }
    const currentId = eanKey(row.retailerProductId);
    if (currentId !== '' && prev.productId !== '' && currentId !== eanKey(prev.productId)) {
      changedProduct.push({
        retailer: row.retailer,
        ean: row.ean,
        name: row.name,
        url: row.url,
        oldName: prev.name,
        oldProductId: prev.productId,
        newProductId: String(row.retailerProductId),
        oldPrice: prev.price,
        newPrice: toNumber(row.effectivePrice),
        fromWeek: prev.week,
        toWeek: row.week,
        matchedBy: row.matchedBy,
        confidence: row.confidence,
      });
      continue;
    }
    const current = toNumber(row.effectivePrice);
    if (current === null || prev.price === 0) continue;
    compared += 1;
    const raw = ((current - prev.price) / prev.price) * 100;
    const change = Math.round(raw * 1e6) / 1e6;
    if (change !== 0 && Math.abs(change) >= thresholdPct) {
      alerts.push({
        retailer: row.retailer,
        ean: row.ean,
        name: row.name,
        url: row.url,
        oldPrice: prev.price,
        newPrice: current,
        changePct: Math.round(raw * 100) / 100,
        direction: change > 0 ? 'up' : 'down',
        fromWeek: prev.week,
        toWeek: row.week,
        matchedBy: row.matchedBy,
        confidence: row.confidence,
      });
    }
  }
  alerts.sort((a, b) => Math.abs(b.changePct) - Math.abs(a.changePct) || a.retailer.localeCompare(b.retailer) || a.ean.localeCompare(b.ean));

  // Priced last week, not priced this week. Skip EANs that are no longer in the
  // list and retailers that were down (they are reported as unavailable instead).
  const requested = new Map();
  for (const e of Array.isArray(flat.eans) ? flat.eans : []) requested.set(eanKey(e), String(e));
  const down = new Set((flat.unavailable || []).map((u) => u.retailer));
  const gone = [];
  if (previousWeek !== null) {
    const listed = new Set();
    for (const r of earlier) {
      const key = `${r.retailer}|${r.ean}`;
      if (r.week !== previousWeek || currentKeys.has(key) || listed.has(key) || down.has(r.retailer)) continue;
      if (requested.size > 0 && !requested.has(r.ean)) continue;
      listed.add(key);
      gone.push({
        retailer: r.retailer,
        ean: requested.get(r.ean) ?? r.ean,
        name: r.name,
        url: r.url,
        lastPrice: r.price,
        lastWeek: r.week,
      });
    }
  }

  // Rows to append: nothing when the week is already in the sheet, and never a
  // row whose week, retailer and EAN are already there.
  let rowsToAppend = [];
  if (!alreadyRecorded) {
    const have = new Set(past.map((r) => `${r.week}|${r.retailer}|${r.ean}`));
    rowsToAppend = flat.rows.filter((row) => !have.has(`${row.week}|${row.retailer}|${eanKey(row.ean)}`));
  }

  const baseline = previousWeek === null;
  let note;
  if (baseline) {
    note = alreadyRecorded
      ? `${thisWeek} is already in the sheet and there is no earlier week to compare with, so nothing was appended.`
      : `Baseline recorded for ${thisWeek}: ${rowsToAppend.length} prices. Alerts start next week, once there is an earlier week to compare with.`;
  } else {
    const different = changedProduct.length > 0 ? `, ${changedProduct.length} matched a different product` : '';
    note = `Compared ${compared} prices with ${previousWeek}: ${alerts.length} moved ${thresholdPct}% or more, ${gone.length} no longer priced${different}.`;
    if (alreadyRecorded) note += ` ${thisWeek} is already in the sheet, so nothing was appended.`;
  }

  // A different product on its own does not send an email; it rides along when
  // something else did.
  const hasAlerts = alerts.length > 0 || gone.length > 0;
  const result = {
    status: 'ok',
    week: thisWeek,
    previousWeek,
    thresholdPct,
    alreadyRecorded,
    baseline,
    note,
    compared,
    newItems,
    hasAlerts,
    moverCount: alerts.length,
    goneCount: gone.length,
    changedProductCount: changedProduct.length,
    alerts,
    gone,
    changedProduct,
    unmatched: flat.unmatched || [],
    unavailable: flat.unavailable || [],
    rejected,
    warnings,
    rowsToAppend,
    summary: '',
    subject: '',
    html: '',
    text: '',
  };
  if (hasAlerts) {
    const many = (n) => (n === 1 ? '' : 's');
    const moved = alerts.length === 0 ? 'No price moved' : `${alerts.length} of ${compared} compared prices moved`;
    result.summary = `${moved} by ${thresholdPct}% or more between ${previousWeek} and ${thisWeek}.`;
    const goneText = gone.length > 0 ? `, ${gone.length} no longer priced` : '';
    const differentText = changedProduct.length > 0 ? `, ${changedProduct.length} matched a different product` : '';
    result.subject = `${alerts.length} grocery price${many(alerts.length)} moved ${thresholdPct}% or more${goneText}${differentText} (${thisWeek})`;
    const email = renderEmail(result, flat, rejected);
    result.html = email.html;
    result.text = email.text;
  }
  return result;
}

