const flat = $('Flatten prices').first().json;
const settings = $('Settings').first().json;
const build = $('Build basket request').first().json;
const history = $input.all().map((item) => item.json);
const result = compareWeeks(flat, history, { thresholdPct: settings.thresholdPct, rejected: build.rejected });
return [{ json: result }];
